package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.junit.Test;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;

/** Configuration, route-availability callbacks and persistence only. Every output source is fake. */
public class SnoreSoundRouteFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);
    private SnoreSoundRouteActivity focused(SnoreSoundRouteActivity previous){long end=SystemClock.elapsedRealtime()+5000;SnoreSoundRouteActivity[] found={null};while(found[0]==null){i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof SnoreSoundRouteActivity&&a!=previous&&a.hasWindowFocus()&&a.getWindow().getDecorView().isAttachedToWindow())found[0]=(SnoreSoundRouteActivity)a;});assertTrue("Focused route screen",found[0]!=null||SystemClock.elapsedRealtime()<end);if(found[0]==null)SystemClock.sleep(30);}return found[0];}
    private void capture(String name)throws Exception{SnoreSoundRouteActivity a=focused(null);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View decor=a.getWindow().getDecorView();decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));device.waitForIdle();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,name+".png")));}
    private void openFromCues(){UiObject2 options=device.wait(Until.findObject(By.desc("Snoring cue options")),5000);assertNotNull(options);options.click();UiObject2 route=device.wait(Until.findObject(By.text("Sound output")),3000);assertNotNull(route);route.click();assertNotNull(focused(null));}
    @Test public void explicitHeadphonePolicyShowsRealAvailabilityAndSurvivesSaveRecreateAndReopen()throws Exception{
        org.junit.Assume.assumeTrue(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"));org.junit.Assume.assumeTrue(InstrumentationRegistry.getArguments().getString("ciReview","").equals("true"));assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));Map<String,?> before=Prefs.of(c).getAll();SnoreSoundRouteActivity.Factory prior=SnoreSoundRouteActivity.factory;SnoringCuesActivity.PreviewFactory previews=SnoringCuesActivity.previewFactory;List<Runnable> listeners=new CopyOnWriteArrayList<>();List<Activity> owned=new CopyOnWriteArrayList<>();AtomicInteger closed=new AtomicInteger();AtomicReference<List<HeadphoneCue.Endpoint>> outputs=new AtomicReference<>(List.of());
        Application application=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a instanceof SnoreSoundRouteActivity||a instanceof SnoringCuesActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};application.registerActivityLifecycleCallbacks(lifecycle);
        try{
            i.runOnMainSync(()->{SnoringCuesActivity.previewFactory=(context,allowed)->{throw new AssertionError("Configuration must not allocate any output");};SnoreSoundRouteActivity.factory=context->{assertFalse(context instanceof Activity);return new SnoreSoundRouteActivity.Source(){Runnable listener;public List<HeadphoneCue.Endpoint> outputs(){return outputs.get();}public void watch(Runnable callback){listener=callback;listeners.add(callback);}public void close(){if(listener!=null){listeners.remove(listener);listener=null;closed.incrementAndGet();}}};};assertTrue(Prefs.of(c).edit().remove("snoreHeadphoneSound").remove("snoreCueRouteError").commit());c.startActivity(new Intent(c,SnoringCuesActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Fake headphone availability · no audio").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));});
            openFromCues();SnoreSoundRouteActivity first=focused(null);assertFalse(device.findObject(By.desc("Headphone sound only")).isChecked());assertFalse(SnoreCueOutput.settings(c).headphoneSound);device.findObject(By.desc("Headphone sound only")).click();assertTrue(device.wait(Until.hasObject(By.desc("Headphone sound only").checked(true)),3000));assertTrue(device.hasObject(By.text("No supported headphones connected. Headphone-only sound will be skipped.")));assertFalse(Prefs.flag(c,"snoreHeadphoneSound"));capture("snore-route-unavailable");
            i.runOnMainSync(()->{outputs.set(List.of(new HeadphoneCue.Endpoint(20,HeadphoneCue.Kind.BLUETOOTH_MEDIA)));for(Runnable listener:listeners)listener.run();});assertTrue(device.wait(Until.hasObject(By.text("Bluetooth media routes cannot be verified as headphones. Use wired, USB or BLE headphones.")),3000));capture("snore-route-bluetooth-unsupported");
            i.runOnMainSync(()->{outputs.set(List.of(new HeadphoneCue.Endpoint(21,HeadphoneCue.Kind.WIRED)));for(Runnable listener:listeners)listener.run();});assertTrue(device.wait(Until.hasObject(By.text("Supported headphones available. Actual routing is checked at each cue.")),3000));capture("snore-route-supported");
            i.runOnMainSync(first::recreate);SnoreSoundRouteActivity replacement=focused(first);assertTrue(device.hasObject(By.desc("Headphone sound only").checked(true)));assertFalse(Prefs.flag(c,"snoreHeadphoneSound"));assertTrue(closed.get()>=1);capture("snore-route-recreated");device.findObject(By.text("Save sound output")).click();assertTrue(device.wait(Until.hasObject(By.desc("Snoring cue options")),5000));assertTrue(SnoreCueOutput.settings(c).headphoneSound);
            openFromCues();assertNotEquals(replacement,focused(replacement));assertTrue(device.hasObject(By.desc("Headphone sound only").checked(true)));capture("snore-route-reopened");device.findObject(By.desc("Headphone sound only")).click();assertTrue(device.wait(Until.hasObject(By.desc("Headphone sound only").checked(false)),3000));device.pressBack();assertTrue(device.wait(Until.hasObject(By.desc("Snoring cue options")),5000));assertTrue("Back discards route draft",Prefs.flag(c,"snoreHeadphoneSound"));assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        }catch(Throwable failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");folder.mkdirs();device.takeScreenshot(new File(folder,"snore-route-failure.png"));device.dumpWindowHierarchy(new File(folder,"snore-route-failure.xml"));}catch(Throwable diagnostic){failure.addSuppressed(diagnostic);}throw failure;}
        finally{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();boolean allDestroyed=true;for(Activity a:owned){long until=SystemClock.elapsedRealtime()+5000;boolean[] gone={false};do{i.runOnMainSync(()->gone[0]=a.isDestroyed());if(!gone[0])SystemClock.sleep(30);}while(!gone[0]&&SystemClock.elapsedRealtime()<until);allDestroyed&=gone[0];}application.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{SnoreSoundRouteActivity.factory=prior;SnoringCuesActivity.previewFactory=previews;SharedPreferences.Editor edit=Prefs.of(c).edit();for(String key:new String[]{"snoreHeadphoneSound","snoreCueRouteError"}){edit.remove(key);Object value=before.get(key);if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof String)edit.putString(key,(String)value);}assertTrue(edit.commit());});assertTrue("Owned Activities destroyed before restoring source factory",allDestroyed);assertTrue("All availability observers detached",listeners.isEmpty());}
    }
}
